package com.gerenciadorrural.modules.inventory.api;
import com.fasterxml.jackson.core.*; import com.fasterxml.jackson.databind.*; import com.gerenciadorrural.modules.inventory.domain.InventoryModels.Status; import java.util.*;
final class InventoryRequestJson {private InventoryRequestJson(){} static void fields(JsonParser p,JsonNode b,Set<String>a)throws JsonMappingException{if(!b.isObject())throw JsonMappingException.from(p,"O comando deve ser um objeto JSON");for(Iterator<String>i=b.fieldNames();i.hasNext();)if(!a.contains(i.next()))throw JsonMappingException.from(p,"A propriedade enviada não é permitida");}static Long version(JsonParser p,JsonNode b)throws JsonMappingException{JsonNode n=b.get("expectedVersion");if(n==null||n.isNull()||!n.isIntegralNumber()||!n.canConvertToLong()||n.longValue()<0)throw JsonMappingException.from(p,"Versão inválida");return n.longValue();}static String text(JsonParser p,JsonNode b,String f,boolean required)throws JsonMappingException{JsonNode n=b.get(f);if(n==null){if(required)throw JsonMappingException.from(p,"Texto obrigatório");return null;}if(n.isNull())return null;if(!n.isTextual())throw JsonMappingException.from(p,"Texto inválido");return n.textValue();}static Status status(JsonParser p,JsonNode b)throws JsonMappingException{JsonNode n=b.get("status");if(n==null||n.isNull()||!n.isTextual())return null;try{return Status.valueOf(n.textValue());}catch(IllegalArgumentException e){throw JsonMappingException.from(p,"Status inválido",e);}}}
